// Host-only replay of the actual, already compiled v2 training step kernel.
// No physics recompilation, inference, reset, reward change, PPO or optimizer.
#include "rl/pond_ppo_task.h"
#include "rl/pond_ppo_contract.h"
#include "quick_identity.h"
#include <cuda.h>
#include <windows.h>
#include <bcrypt.h>
#include <algorithm>
#include <chrono>
#include <climits>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>
namespace fs=std::filesystem;namespace cp=cudarl::checkpoint;namespace pr=cudarl::pond_runtime;
namespace pt=cudarl::rl::pond_ppo_task;namespace pp=cudarl::rl::pond_ppo;namespace p=cudarl::physics;
namespace {
using Clock=std::chrono::steady_clock;constexpr int N=512,D=41,A=4;
constexpr uint64_t FrozenSource=16308029809216107606ull;
constexpr char TrainerSHA[]="c595a3348a4fa61412aeba8a8f7e744aa4b787ad06509ed553810c24491303c7";
struct Trace {float x,z,vx,vy,vz,depth,tilt;double gap;uint32_t episode,control,kind,cells,grid[8];float near_s,contact_s,stall_s;};
static_assert(sizeof(pr::World)==1384&&sizeof(pt::Task)==184&&sizeof(Trace)==104);
static_assert(pr::version==4&&pt::version==2&&pp::observation_schema==5);
void require(bool yes,const std::string& why){if(!yes)throw std::runtime_error(why);}
void drv(CUresult code){if(code!=CUDA_SUCCESS){const char* s=nullptr;cuGetErrorString(code,&s);throw std::runtime_error(s?s:"CUDA driver error");}}
double elapsed(Clock::time_point t){return std::chrono::duration<double,std::milli>(Clock::now()-t).count();}
std::string esc(const std::string& s){std::string out;for(char c:s){if(c=='"'||c=='\\')out+='\\';if(c=='\n')out+="\\n";else out+=c;}return out;}
std::vector<uint8_t> read(const fs::path& path){std::ifstream f(path,std::ios::binary|std::ios::ate);require(bool(f),"Cannot read "+path.string());const auto n=f.tellg();require(n>=0&&n<200000000,"Input size limit");std::vector<uint8_t>b(static_cast<size_t>(n));f.seekg(0);f.read(reinterpret_cast<char*>(b.data()),n);require(bool(f),"Incomplete input");return b;}
std::string sha(const std::vector<uint8_t>& b){BCRYPT_ALG_HANDLE a=nullptr;BCRYPT_HASH_HANDLE h=nullptr;UCHAR digest[32]{};require(BCryptOpenAlgorithmProvider(&a,BCRYPT_SHA256_ALGORITHM,nullptr,0)>=0,"SHA provider");require(BCryptCreateHash(a,&h,nullptr,0,nullptr,0,0)>=0,"SHA create");require(BCryptHashData(h,const_cast<PUCHAR>(b.data()),static_cast<ULONG>(b.size()),0)>=0,"SHA data");require(BCryptFinishHash(h,digest,32,0)>=0,"SHA finish");BCryptDestroyHash(h);BCryptCloseAlgorithmProvider(a,0);std::ostringstream s;for(auto v:digest)s<<std::hex<<std::setfill('0')<<std::setw(2)<<unsigned(v);return s.str();}
void write(const fs::path& path,const std::string& s){std::ofstream f(path,std::ios::binary);f<<s;f.flush();require(bool(f),"Evidence write failed");}
template<class T>std::vector<uint8_t> bytes(const std::vector<T>& v){const auto* b=reinterpret_cast<const uint8_t*>(v.data());return {b,b+v.size()*sizeof(T)};}
struct Fixture {uint32_t update=0;std::string batch_sha;std::vector<uint8_t> worlds,tasks;std::vector<float> latent,reward,done,truncated;std::vector<uint64_t> attempted,steps;std::vector<int> reason;std::vector<uint8_t> trace;double input_read_ms=0;};
template<class T>std::vector<T> first(std::vector<T> v,size_t count){require(v.size()>=count,"Short recorded array");v.resize(count);return v;}
Fixture extract(const fs::path& path,uint32_t expected){const auto t=Clock::now();const auto raw=read(path);auto payload=cp::read(path.string());Fixture f;f.input_read_ms=elapsed(t);f.batch_sha=sha(raw);cp::Reader r{payload};require(r.value<uint32_t>()==0x31425450&&r.value<uint32_t>()==1,"Wrong batch schema");f.update=r.value<uint32_t>();require(f.update==expected&&r.value<int>()==64,"Wrong batch update/horizon");(void)r.value<uint64_t>();require(r.value<uint64_t>()==FrozenSource,"Not frozen v2 source");
 f.worlds=r.array<uint8_t>();f.tasks=r.array<uint8_t>();require(f.worlds.size()==N*sizeof(pr::World)&&f.tasks.size()==N*sizeof(pt::Task),"Wrong world/task ABI");require(r.array<float>().size()==2532&&r.array<float>().size()==2433,"Wrong actor/critic sizes");
 require(r.array<float>().size()==N*64*D,"Wrong observation rows");f.latent=first(r.array<float>(),N*A);require(r.array<float>().size()==N*64&&r.array<float>().size()==N*64,"Wrong logp/value rows");f.reward=first(r.array<float>(),N);f.done=first(r.array<float>(),N);f.truncated=first(r.array<float>(),N);(void)r.array<float>();(void)r.array<float>();f.attempted=first(r.array<uint64_t>(),N);f.steps=first(r.array<uint64_t>(),N);f.reason=first(r.array<int>(),N);require(r.value<uint32_t>()==sizeof(Trace),"Wrong trace ABI");f.trace=first(r.array<uint8_t>(),N*sizeof(Trace));r.finish();for(int i=0;i<N;++i)require(f.attempted[i]==1&&f.steps[i]==10,"Original first control not complete");return f;}
void put(cp::Writer& w,const Fixture& f){w.value(f.update);w.array(std::vector<uint8_t>(f.batch_sha.begin(),f.batch_sha.end()));w.array(f.worlds);w.array(f.tasks);w.array(f.latent);w.array(f.reward);w.array(f.done);w.array(f.truncated);w.array(f.attempted);w.array(f.steps);w.array(f.reason);w.array(f.trace);}
Fixture get(cp::Reader& r){Fixture f;f.update=r.value<uint32_t>();const auto hash=r.array<uint8_t>(64);f.batch_sha={hash.begin(),hash.end()};f.worlds=r.array<uint8_t>();f.tasks=r.array<uint8_t>();f.latent=r.array<float>();f.reward=r.array<float>();f.done=r.array<float>();f.truncated=r.array<float>();f.attempted=r.array<uint64_t>();f.steps=r.array<uint64_t>();f.reason=r.array<int>();f.trace=r.array<uint8_t>();require(f.worlds.size()==N*sizeof(pr::World)&&f.tasks.size()==N*sizeof(pt::Task)&&f.latent.size()==N*A,"Prepared ABI mismatch");return f;}
struct Options{bool prepare=false,run=false;fs::path batch1,batch32,module,trainer,fixture,out;std::string symbol;};
Options options(int argc,char** argv){Options o;for(int i=1;i<argc;++i){std::string a=argv[i];const auto next=[&](){require(i+1<argc,"Missing option value");return std::string(argv[++i]);};if(a=="--prepare")o.prepare=true;else if(a=="--run")o.run=true;else if(a=="--batch1")o.batch1=next();else if(a=="--batch32")o.batch32=next();else if(a=="--module")o.module=next();else if(a=="--trainer")o.trainer=next();else if(a=="--fixture")o.fixture=next();else if(a=="--symbol")o.symbol=next();else if(a=="--out")o.out=next();else throw std::runtime_error("Unknown option "+a);}require(o.prepare!=o.run&&!o.out.empty()&&!o.module.empty()&&!o.symbol.empty(),"Require prepare/run, module, symbol and unique out");require(!fs::exists(o.out)&&fs::create_directories(o.out),"Output already exists");return o;}
struct Device {CUdeviceptr p=0;size_t n;explicit Device(size_t size):n(size){drv(cuMemAlloc(&p,n));}~Device(){if(p)cuMemFree(p);}};
struct Buffers {Device world{N*sizeof(pr::World)},task{N*sizeof(pt::Task)},latent{N*A*4},reward{N*4},done{N*4},truncated{N*4},obs{N*D*4},attempted{N*8},steps{N*8},reason{N*4},trace{N*sizeof(Trace)},fault{4};};
struct Result {std::vector<uint8_t> world,task,trace;std::vector<float>reward,done,truncated,obs;std::vector<uint64_t>attempted,steps;std::vector<int>reason;int fault=INT_MAX;};
template<class T>void copy_back(std::vector<T>& v,Device& d){v.resize(d.n/sizeof(T));drv(cuMemcpyDtoH(v.data(),d.p,d.n));}
Result download(Buffers& b){Result r;copy_back(r.world,b.world);copy_back(r.task,b.task);copy_back(r.trace,b.trace);copy_back(r.reward,b.reward);copy_back(r.done,b.done);copy_back(r.truncated,b.truncated);copy_back(r.obs,b.obs);copy_back(r.attempted,b.attempted);copy_back(r.steps,b.steps);copy_back(r.reason,b.reason);drv(cuMemcpyDtoH(&r.fault,b.fault.p,4));return r;}
void upload(Buffers& b,const Fixture& f){drv(cuMemcpyHtoD(b.world.p,f.worlds.data(),b.world.n));drv(cuMemcpyHtoD(b.task.p,f.tasks.data(),b.task.n));drv(cuMemcpyHtoD(b.latent.p,f.latent.data(),b.latent.n));for(Device* d:{&b.reward,&b.done,&b.truncated,&b.obs,&b.attempted,&b.steps,&b.reason,&b.trace})drv(cuMemsetD8(d->p,0,d->n));const int good=INT_MAX;drv(cuMemcpyHtoD(b.fault.p,&good,4));}
template<class T>bool equal(const std::vector<T>& a,const std::vector<T>& b){return a.size()==b.size()&&std::memcmp(a.data(),b.data(),a.size()*sizeof(T))==0;}
bool trace_equal(const std::vector<uint8_t>& a,const std::vector<uint8_t>& b,int i){return a.size()==b.size()&&std::memcmp(a.data()+i*104,b.data()+i*104,28)==0&&std::memcmp(a.data()+i*104+32,b.data()+i*104+32,68)==0;}
bool same(const Result&a,const Result&b){bool yes=a.fault==b.fault&&equal(a.world,b.world)&&equal(a.task,b.task)&&equal(a.reward,b.reward)&&equal(a.done,b.done)&&equal(a.truncated,b.truncated)&&equal(a.obs,b.obs)&&equal(a.attempted,b.attempted)&&equal(a.steps,b.steps)&&equal(a.reason,b.reason);for(int i=0;i<N;++i)yes=yes&&trace_equal(a.trace,b.trace,i);return yes;}
bool recorded(const Result&r,const Fixture&f){bool yes=equal(r.reward,f.reward)&&equal(r.done,f.done)&&equal(r.truncated,f.truncated)&&equal(r.attempted,f.attempted)&&equal(r.steps,f.steps)&&equal(r.reason,f.reason);for(int i=0;i<N;++i)yes=yes&&trace_equal(r.trace,f.trace,i);return yes;}
void save(const fs::path& path,const Result&r){cp::Writer w;w.value(uint32_t{0x31525150});w.array(r.world);w.array(r.task);w.array(r.reward);w.array(r.done);w.array(r.truncated);w.array(r.obs);w.array(r.attempted);w.array(r.steps);w.array(r.reason);w.array(r.trace);w.value(r.fault);cp::write_atomic(path.string(),w.data);}
struct Context {CUcontext c=nullptr;CUdevice d=0;Context(){drv(cuInit(0));drv(cuDeviceGet(&d,0));drv(cuDevicePrimaryCtxRetain(&c,d));drv(cuCtxSetCurrent(c));}~Context(){if(c)cuDevicePrimaryCtxRelease(d);}};
struct Module{CUmodule m=nullptr;explicit Module(const fs::path&p){drv(cuModuleLoad(&m,p.string().c_str()));}~Module(){if(m)cuModuleUnload(m);}};
struct Events{CUevent a=nullptr,b=nullptr;Events(){drv(cuEventCreate(&a,0));drv(cuEventCreate(&b,0));}~Events(){if(a)cuEventDestroy(a);if(b)cuEventDestroy(b);}};
int prepare(const Options&o){const auto t=Clock::now();const auto trainer=read(o.trainer);require(sha(trainer)==TrainerSHA,"Not exact frozen v2 trainer executable");const auto m=read(o.module);const auto one=extract(o.batch1,1),late=extract(o.batch32,32);cp::Writer w;w.value(uint32_t{0x31585150});w.value(uint32_t{1});w.value(FrozenSource);const auto mh=sha(m);w.array(std::vector<uint8_t>(mh.begin(),mh.end()));w.array(std::vector<uint8_t>(o.symbol.begin(),o.symbol.end()));put(w,one);put(w,late);cp::write_atomic((o.out/"fixtures.bin").string(),w.data);std::ostringstream s;s<<std::setprecision(17)<<"{\"prepared\":true,\"source_sha256\":\""<<quick_source_sha256<<"\",\"trainer_sha256\":\""<<TrainerSHA<<"\",\"module_sha256\":\""<<mh<<"\",\"batch1_sha256\":\""<<one.batch_sha<<"\",\"batch32_sha256\":\""<<late.batch_sha<<"\",\"batch1_read_checksum_ms\":"<<one.input_read_ms<<",\"batch32_read_checksum_ms\":"<<late.input_read_ms<<",\"wall_ms\":"<<elapsed(t)<<",\"fixture_bytes\":"<<w.data.size()+24<<",\"physical_controls\":0,\"CUDA_calls\":0,\"optimizer_calls\":0}\n";write(o.out/"preparation.json",s.str());std::cout<<s.str();return 0;}
int run(const Options&o){const auto started=Clock::now();const auto rstart=Clock::now();const auto payload=cp::read(o.fixture.string());cp::Reader r{payload};require(r.value<uint32_t>()==0x31585150&&r.value<uint32_t>()==1&&r.value<uint64_t>()==FrozenSource,"Wrong prepared fixture");const auto hash=r.array<uint8_t>(64),symbol=r.array<uint8_t>(1000);require(std::string(symbol.begin(),symbol.end())==o.symbol&&sha(read(o.module))==std::string(hash.begin(),hash.end()),"Module/symbol binding mismatch");auto one=get(r),late=get(r);r.finish();const double read_ms=elapsed(rstart);const auto init=Clock::now();Context context;Module module(o.module);CUfunction kernel=nullptr;drv(cuModuleGetFunction(&kernel,module.m,o.symbol.c_str()));int sms=0,registers=0,local=0;char name[256]{};drv(cuDeviceGetAttribute(&sms,CU_DEVICE_ATTRIBUTE_MULTIPROCESSOR_COUNT,context.d));drv(cuDeviceGetName(name,256,context.d));drv(cuFuncGetAttribute(&registers,CU_FUNC_ATTRIBUTE_NUM_REGS,kernel));drv(cuFuncGetAttribute(&local,CU_FUNC_ATTRIBUTE_LOCAL_SIZE_BYTES,kernel));Buffers b;Events events;const double init_ms=elapsed(init);uint64_t attempted=0,steps=0,scheduled=0;std::ostringstream rows,csv;rows<<std::setprecision(17);csv<<"batch,threads,blocks,world,attempted,substeps,reason,failure,reference_equal,recorded_equal\n";bool okay=true;std::string failure;double evidence_ms=0;int launches=0;
 try{for(const auto* fixture:{&one,&late}){Result reference;for(const int threads:{32,8,1}){require(elapsed(started)<30000,"Thirty-second launch reserve exhausted");const auto up=Clock::now();upload(b,*fixture);const double upload_ms=elapsed(up);float gain=pp::frozen_holding_gain;void* args[]={&b.world.p,&b.task.p,&b.latent.p,&gain,&b.reward.p,&b.done.p,&b.truncated.p,&b.obs.p,&b.attempted.p,&b.steps.p,&b.reason.p,&b.trace.p,&b.fault.p};const auto wall=Clock::now();drv(cuEventRecord(events.a,nullptr));scheduled+=N;++launches;drv(cuLaunchKernel(kernel,N/threads,1,1,threads,1,1,0,nullptr,args,nullptr));drv(cuEventRecord(events.b,nullptr));drv(cuEventSynchronize(events.b));float event_ms=0;drv(cuEventElapsedTime(&event_ms,events.a,events.b));const double launch_wall=elapsed(wall);const auto down=Clock::now();const auto actual=download(b);const double download_ms=elapsed(down);if(threads==32)reference=actual;const bool bitwise=same(actual,reference),native=recorded(actual,*fixture);bool valid=actual.fault==INT_MAX;for(int i=0;i<N;++i){attempted+=actual.attempted[i];steps+=actual.steps[i];pr::World world;std::memcpy(&world,actual.world.data()+i*sizeof(world),sizeof(world));valid=valid&&actual.attempted[i]==1&&actual.steps[i]==10&&world.failure==0;csv<<fixture->update<<','<<threads<<','<<N/threads<<','<<i<<','<<actual.attempted[i]<<','<<actual.steps[i]<<','<<actual.reason[i]<<','<<world.failure<<','<<(bitwise?1:0)<<','<<(native?1:0)<<'\n';}
 const auto io=Clock::now();save(o.out/("batch"+std::to_string(fixture->update)+"-threads"+std::to_string(threads)+".bin"),actual);const double io_ms=elapsed(io);evidence_ms+=io_ms;if(launches>1)rows<<',';rows<<"{\"batch\":"<<fixture->update<<",\"threads\":"<<threads<<",\"blocks\":"<<N/threads<<",\"event_ms\":"<<event_ms<<",\"launch_wall_ms\":"<<launch_wall<<",\"upload_ms\":"<<upload_ms<<",\"download_ms\":"<<download_ms<<",\"evidence_write_ms\":"<<io_ms<<",\"bitwise_equal_to_32\":"<<(bitwise?"true":"false")<<",\"recorded_native_outputs_equal\":"<<(native?"true":"false")<<",\"valid\":"<<(valid?"true":"false")<<'}';okay=okay&&bitwise&&native&&valid;require(okay,"Matched replay/status disagreement; no further launches");}}}catch(const std::exception&e){okay=false;failure=e.what();}
 const auto io=Clock::now();write(o.out/"worlds.csv",csv.str());evidence_ms+=elapsed(io);std::ostringstream s;s<<std::setprecision(17)<<"{\"protocol_id\":\"pond-frozen-v2-quick-layout-v1\",\"passed\":"<<(okay&&launches==6?"true":"false")<<",\"failure\":\""<<esc(failure)<<"\",\"source_sha256\":\""<<quick_source_sha256<<"\",\"frozen_trainer_source_fnv\":\""<<FrozenSource<<"\",\"device\":\""<<esc(name)<<"\",\"SM_count\":"<<sms<<",\"registers_per_thread\":"<<registers<<",\"local_bytes_per_thread\":"<<local<<",\"fixture_read_and_module_hash_ms\":"<<read_ms<<",\"CUDA_context_module_allocation_ms\":"<<init_ms<<",\"evidence_write_ms\":"<<evidence_ms<<",\"process_internal_wall_ms\":"<<elapsed(started)<<",\"world_controls_confirmed\":"<<attempted<<",\"substeps_confirmed\":"<<steps<<",\"world_controls_upper_bound\":"<<scheduled<<",\"maximum_world_controls\":3072,\"optimizer_calls\":0,\"inference_calls\":0,\"resets\":0,\"integration_warmups\":0,\"trace_padding_excluded_bytes_per_row\":8,\"launches\":["<<rows.str()<<"]}\n";write(o.out/"result.json",s.str());std::cout<<s.str();return okay&&launches==6?0:2;}
}
int main(int argc,char** argv){try{const auto o=options(argc,argv);return o.prepare?prepare(o):run(o);}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
